  mutual_count INT4 NOT NULL DEFAULT 0,
  primary_pymk_signal_type_id UUID NOT NULL,
  model_version STRING(32) NOT NULL,
  generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL DEFAULT now() + INTERVAL '14 days',
  CONSTRAINT pk_pymk_candidate PRIMARY KEY (id),
  CONSTRAINT uq_pymk_candidate_app_user_id_suggested_app_user_id UNIQUE (app_user_id, suggested_app_user_id),
  CONSTRAINT ck_pymk_candidate_not_self CHECK (app_user_id <> suggested_app_user_id),
  CONSTRAINT fk_pymk_candidate_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_pymk_candidate_suggested_app_user_id FOREIGN KEY (suggested_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_pymk_candidate_primary_pymk_signal_type_id FOREIGN KEY (primary_pymk_signal_type_id) REFERENCES pymk_signal_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_pymk_candidate_app_user_id_score (app_user_id, score DESC) STORING (suggested_app_user_id, mutual_count),
  INDEX idx_pymk_candidate_suggested_app_user_id (suggested_app_user_id),
  INDEX idx_pymk_candidate_expires_at (expires_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_pymk_candidate_primary_pymk_signal_type_id (primary_pymk_signal_type_id)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
