  CONSTRAINT pk_connection PRIMARY KEY (id),
  CONSTRAINT uq_connection_lo_app_user_id_hi_app_user_id UNIQUE (lo_app_user_id, hi_app_user_id),
  CONSTRAINT ck_connection_canonical_order CHECK (lo_app_user_id < hi_app_user_id),
  CONSTRAINT ck_connection_initiator_is_member CHECK (initiator_app_user_id IN (lo_app_user_id, hi_app_user_id)),
  CONSTRAINT fk_connection_lo_app_user_id FOREIGN KEY (lo_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_connection_hi_app_user_id FOREIGN KEY (hi_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_connection_connection_origin_id FOREIGN KEY (connection_origin_id) REFERENCES connection_origin (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_connection_initiator_app_user_id FOREIGN KEY (initiator_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_connection_connection_request_id FOREIGN KEY (connection_request_id) REFERENCES connection_request (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_connection_lo_app_user_id_connected_at_adj (lo_app_user_id, connected_at DESC) STORING (hi_app_user_id),
  INDEX idx_connection_hi_app_user_id_connected_at_adj (hi_app_user_id, connected_at DESC) STORING (lo_app_user_id),
  INDEX idx_connection_connection_request_id (connection_request_id) WHERE connection_request_id IS NOT NULL,
  INDEX idx_connection_connection_origin_id (connection_origin_id),
  INDEX idx_connection_initiator_app_user_id (initiator_app_user_id)
);
