CREATE TABLE IF NOT EXISTS event (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organiser_app_user_id UUID NOT NULL,
  organiser_organisation_id UUID,
  community_group_id UUID,
  event_type_id UUID NOT NULL,
  event_format_id UUID NOT NULL,
  event_status_id UUID NOT NULL,
  visibility_level_id UUID NOT NULL,
  language_id UUID NOT NULL,
  slug STRING(100) NOT NULL,
  title STRING(200) NOT NULL,
  description_text STRING NOT NULL,
  starts_at TIMESTAMPTZ NOT NULL,
  ends_at TIMESTAMPTZ NOT NULL,
  time_zone STRING(64) NOT NULL,
  venue_name STRING(200),
  city_id UUID,
  country_id UUID,
  join_url STRING(500),
  banner_image_url STRING(500),
  capacity INT4,
  is_ticketed BOOL NOT NULL DEFAULT false,
  registration_closes_at TIMESTAMPTZ,
  CONSTRAINT pk_event PRIMARY KEY (id),
  CONSTRAINT ck_event_ends_after_starts CHECK (ends_at >= starts_at),
  CONSTRAINT ck_event_registration_before_end CHECK (registration_closes_at IS NULL OR registration_closes_at <= ends_at),
  CONSTRAINT ck_event_capacity_positive CHECK (capacity IS NULL OR capacity > 0),
  CONSTRAINT fk_event_organiser_app_user_id FOREIGN KEY (organiser_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_event_organiser_organisation_id FOREIGN KEY (organiser_organisation_id) REFERENCES organisation (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_event_community_group_id FOREIGN KEY (community_group_id) REFERENCES community_group (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_event_event_type_id FOREIGN KEY (event_type_id) REFERENCES event_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_event_event_format_id FOREIGN KEY (event_format_id) REFERENCES event_format (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_event_event_status_id FOREIGN KEY (event_status_id) REFERENCES event_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_event_visibility_level_id FOREIGN KEY (visibility_level_id) REFERENCES visibility_level (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_event_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_event_city_id FOREIGN KEY (city_id) REFERENCES city (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_event_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_event_slug_live (slug) WHERE deleted_at IS NULL,
  INDEX idx_event_starts_at_upcoming (starts_at) WHERE deleted_at IS NULL,
  INDEX idx_event_organiser_app_user_id_starts_at (organiser_app_user_id, starts_at DESC),
  INDEX idx_event_organiser_organisation_id_starts_at_page (organiser_organisation_id, starts_at DESC) WHERE organiser_organisation_id IS NOT NULL,
  INDEX idx_event_community_group_id_starts_at_group (community_group_id, starts_at DESC) WHERE community_group_id IS NOT NULL,
  INDEX idx_event_city_id_starts_at_local (city_id, starts_at) WHERE city_id IS NOT NULL,
  INDEX idx_event_event_status_id_starts_at (event_status_id, starts_at),
  INDEX idx_event_event_type_id (event_type_id),
  INDEX idx_event_event_format_id (event_format_id),
  INDEX idx_event_visibility_level_id (visibility_level_id),
  INDEX idx_event_language_id (language_id),
  INDEX idx_event_country_id (country_id)
);
