  INDEX idx_profile_visitor_daily_owner_app_user_id_visit_date (owner_app_user_id, visit_date DESC) STORING (visitor_app_user_id, visit_count),
  INDEX idx_profile_visitor_daily_visitor_app_user_id_erasure (visitor_app_user_id) WHERE visitor_app_user_id IS NOT NULL,
  INDEX idx_profile_visitor_daily_expires_at (expires_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_profile_visitor_daily_profile_visit_mode_id (profile_visit_mode_id),
  INDEX idx_profile_visitor_daily_view_source_id (view_source_id),
  INDEX idx_profile_visitor_daily_visitor_organisation_id (visitor_organisation_id),
  INDEX idx_profile_visitor_daily_visitor_job_role_id (visitor_job_role_id)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
