  CONSTRAINT ck_user_badge_revoked_after_awarded CHECK (revoked_at IS NULL OR revoked_at >= awarded_at),
  CONSTRAINT ck_user_badge_expiry_after_award CHECK (expires_at IS NULL OR expires_at >= awarded_at),
  CONSTRAINT fk_user_badge_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
