  INDEX idx_user_badge_badge_type_id_awarded_at (badge_type_id, awarded_at),
  INDEX idx_user_badge_issuer_organisation_id_issuer (issuer_organisation_id) WHERE issuer_organisation_id IS NOT NULL,
  INDEX idx_user_badge_issuer_institution_id_issuer (issuer_institution_id) WHERE issuer_institution_id IS NOT NULL,
  INDEX idx_user_badge_expires_at_due (expires_at) WHERE revoked_at IS NULL AND expires_at IS NOT NULL,
  INDEX idx_user_badge_badge_issuer_kind_id (badge_issuer_kind_id),
  INDEX idx_user_badge_verification_status_id (verification_status_id)
);
