  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  institution_id UUID NOT NULL,
  alumnus_app_user_id UUID NOT NULL,
  candidate_education_id UUID,
  alumni_link_status_id UUID NOT NULL,
  qualification_id UUID,
  graduation_year INT2,
  verified_at TIMESTAMPTZ,
  verified_by_app_user_id UUID,
  CONSTRAINT pk_alumni_membership PRIMARY KEY (id),
  CONSTRAINT ck_alumni_membership_year_range CHECK (graduation_year IS NULL OR graduation_year BETWEEN 1900 AND 2100),
  CONSTRAINT fk_alumni_membership_institution_id FOREIGN KEY (institution_id) REFERENCES institution (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_alumni_membership_alumnus_app_user_id FOREIGN KEY (alumnus_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_alumni_membership_candidate_education_id FOREIGN KEY (candidate_education_id) REFERENCES candidate_education (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_alumni_membership_alumni_link_status_id FOREIGN KEY (alumni_link_status_id) REFERENCES alumni_link_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_alumni_membership_qualification_id FOREIGN KEY (qualification_id) REFERENCES qualification (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_alumni_membership_verified_by_app_user_id FOREIGN KEY (verified_by_app_user_id) REFERENCES app_user (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_alumni_membership_institution_id_alumnus_app_user_id_pair (institution_id, alumnus_app_user_id) WHERE alumni_link_status_id IS NOT NULL,
  INDEX idx_alumni_membership_alumnus_app_user_id (alumnus_app_user_id),
  INDEX idx_alumni_membership_institution_id_graduation_year (institution_id, graduation_year),
  INDEX idx_alumni_membership_candidate_education_id (candidate_education_id),
  INDEX idx_alumni_membership_alumni_link_status_id (alumni_link_status_id),
  INDEX idx_alumni_membership_qualification_id (qualification_id),
  INDEX idx_alumni_membership_verified_by_app_user_id (verified_by_app_user_id)
);
