CREATE TABLE IF NOT EXISTS connection_note (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  owner_app_user_id UUID NOT NULL,
  subject_app_user_id UUID NOT NULL,
  note_text STRING(2000) NOT NULL,
  met_on_date DATE,
  met_event_id UUID,
  remind_at TIMESTAMPTZ,
  CONSTRAINT pk_connection_note PRIMARY KEY (id),
  CONSTRAINT uq_connection_note_owner_app_user_id_subject_app_user_id UNIQUE (owner_app_user_id, subject_app_user_id),
  CONSTRAINT ck_connection_note_not_self CHECK (owner_app_user_id <> subject_app_user_id),
  CONSTRAINT fk_connection_note_owner_app_user_id FOREIGN KEY (owner_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_connection_note_subject_app_user_id FOREIGN KEY (subject_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_connection_note_met_event_id FOREIGN KEY (met_event_id) REFERENCES event (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_connection_note_subject_app_user_id (subject_app_user_id),
  INDEX idx_connection_note_remind_at_due (remind_at) WHERE remind_at IS NOT NULL,
  INDEX idx_connection_note_met_event_id (met_event_id)
);
