CREATE TABLE IF NOT EXISTS endorsement_request (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  requester_app_user_id UUID NOT NULL,
  requested_app_user_id UUID NOT NULL,
  candidate_skill_id UUID NOT NULL,
  assist_request_status_id UUID NOT NULL,
  message_text STRING(500),
  candidate_skill_endorsement_id UUID,
  is_pending BOOL NOT NULL DEFAULT false,
  requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  responded_at TIMESTAMPTZ,
  CONSTRAINT pk_endorsement_request PRIMARY KEY (id),
  CONSTRAINT ck_endorsement_request_not_self CHECK (requester_app_user_id <> requested_app_user_id),
  CONSTRAINT ck_endorsement_request_responded_after CHECK (responded_at IS NULL OR responded_at >= requested_at),
  CONSTRAINT fk_endorsement_request_requester_app_user_id FOREIGN KEY (requester_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_endorsement_request_requested_app_user_id FOREIGN KEY (requested_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_endorsement_request_candidate_skill_id FOREIGN KEY (candidate_skill_id) REFERENCES candidate_skill (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_endorsement_request_assist_request_status_id FOREIGN KEY (assist_request_status_id) REFERENCES assist_request_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_endorsement_request_candidate_skill_endorsement_id FOREIGN KEY (candidate_skill_endorsement_id) REFERENCES candidate_skill_endorsement (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_endorsement_request_candidate_skill_id_requested_app_user_id_open (candidate_skill_id, requested_app_user_id) WHERE is_pending,
  INDEX idx_endorsement_request_requested_app_user_id_requested_at_inbox (requested_app_user_id, requested_at DESC) WHERE is_pending,
  INDEX idx_endorsement_request_requester_app_user_id_requested_at (requester_app_user_id, requested_at DESC),
  INDEX idx_endorsement_request_assist_request_status_id (assist_request_status_id),
  INDEX idx_endorsement_request_candidate_skill_endorsement_id (candidate_skill_endorsement_id)
);
