CREATE TABLE IF NOT EXISTS event_rsvp (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  event_id UUID NOT NULL,
  attendee_app_user_id UUID NOT NULL,
  event_rsvp_status_id UUID NOT NULL,
  event_ticket_type_id UUID,
  connection_origin_id UUID NOT NULL,
  guest_count INT4 NOT NULL DEFAULT 0,
  responded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_event_rsvp PRIMARY KEY (id),
  CONSTRAINT uq_event_rsvp_event_id_attendee_app_user_id UNIQUE (event_id, attendee_app_user_id),
  CONSTRAINT ck_event_rsvp_guest_range CHECK (guest_count BETWEEN 0 AND 10),
  CONSTRAINT fk_event_rsvp_event_id FOREIGN KEY (event_id) REFERENCES event (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_event_rsvp_attendee_app_user_id FOREIGN KEY (attendee_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_event_rsvp_event_rsvp_status_id FOREIGN KEY (event_rsvp_status_id) REFERENCES event_rsvp_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_event_rsvp_event_ticket_type_id FOREIGN KEY (event_ticket_type_id) REFERENCES event_ticket_type (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_event_rsvp_connection_origin_id FOREIGN KEY (connection_origin_id) REFERENCES connection_origin (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_event_rsvp_attendee_app_user_id_responded_at (attendee_app_user_id, responded_at DESC),
  INDEX idx_event_rsvp_event_id_event_rsvp_status_id (event_id, event_rsvp_status_id),
  INDEX idx_event_rsvp_event_rsvp_status_id (event_rsvp_status_id),
  INDEX idx_event_rsvp_event_ticket_type_id (event_ticket_type_id),
  INDEX idx_event_rsvp_connection_origin_id (connection_origin_id)
);
