  CONSTRAINT fk_recommendation_request_requester_app_user_id FOREIGN KEY (requester_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_recommendation_request_requested_app_user_id FOREIGN KEY (requested_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
