  INDEX idx_recommendation_request_relationship_type_id (relationship_type_id),
  INDEX idx_recommendation_request_candidate_experience_id (candidate_experience_id),
  INDEX idx_recommendation_request_assist_request_status_id (assist_request_status_id),
  INDEX idx_recommendation_request_candidate_recommendation_id (candidate_recommendation_id)
