  CONSTRAINT fk_event_ticket_event_ticket_type_id FOREIGN KEY (event_ticket_type_id) REFERENCES event_ticket_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_event_ticket_payment_order_id FOREIGN KEY (payment_order_id) REFERENCES payment_order (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_event_ticket_event_rsvp_id_rsvp (event_rsvp_id),
  INDEX idx_event_ticket_payment_order_id_paid (payment_order_id) WHERE payment_order_id IS NOT NULL,
  INDEX idx_event_ticket_event_ticket_type_id (event_ticket_type_id)
);
