CREATE TABLE IF NOT EXISTS user_signal (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  app_user_id UUID NOT NULL,
  network_signal_type_id UUID NOT NULL,
  visibility_level_id UUID NOT NULL,
  candidate_open_to_work_signal_id UUID,
  headline_text STRING(120),
  job_role_id UUID,
  city_id UUID,
  job_requirement_id UUID,
  show_frame BOOL NOT NULL DEFAULT true,
  starts_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ends_at TIMESTAMPTZ,
  CONSTRAINT pk_user_signal PRIMARY KEY (id),
  CONSTRAINT ck_user_signal_ends_after_starts CHECK (ends_at IS NULL OR ends_at >= starts_at),
  CONSTRAINT fk_user_signal_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_user_signal_network_signal_type_id FOREIGN KEY (network_signal_type_id) REFERENCES network_signal_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_signal_visibility_level_id FOREIGN KEY (visibility_level_id) REFERENCES visibility_level (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_signal_candidate_open_to_work_signal_id FOREIGN KEY (candidate_open_to_work_signal_id) REFERENCES candidate_open_to_work_signal (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_user_signal_job_role_id FOREIGN KEY (job_role_id) REFERENCES job_role (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_user_signal_city_id FOREIGN KEY (city_id) REFERENCES city (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_user_signal_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_user_signal_app_user_id_network_signal_type_id_open (app_user_id, network_signal_type_id) WHERE ends_at IS NULL,
  INDEX idx_user_signal_network_signal_type_id_city_id_open (network_signal_type_id, city_id) WHERE ends_at IS NULL,
  INDEX idx_user_signal_job_requirement_id_job (job_requirement_id) WHERE job_requirement_id IS NOT NULL,
  INDEX idx_user_signal_job_role_id_open (job_role_id) WHERE job_role_id IS NOT NULL,
  INDEX idx_user_signal_visibility_level_id (visibility_level_id),
  INDEX idx_user_signal_candidate_open_to_work_signal_id (candidate_open_to_work_signal_id),
  INDEX idx_user_signal_city_id (city_id)
);
