CREATE TABLE IF NOT EXISTS event_attendance (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  event_id UUID NOT NULL,
  event_session_id UUID,
  attendee_app_user_id UUID NOT NULL,
  event_ticket_id UUID,
  event_attendance_source_id UUID NOT NULL,
  checked_in_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  attended_seconds INT4,
  CONSTRAINT pk_event_attendance PRIMARY KEY (id),
  CONSTRAINT fk_event_attendance_event_id FOREIGN KEY (event_id) REFERENCES event (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_event_attendance_event_session_id FOREIGN KEY (event_session_id) REFERENCES event_session (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_event_attendance_attendee_app_user_id FOREIGN KEY (attendee_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_event_attendance_event_ticket_id FOREIGN KEY (event_ticket_id) REFERENCES event_ticket (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_event_attendance_event_attendance_source_id FOREIGN KEY (event_attendance_source_id) REFERENCES event_attendance_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_event_attendance_event_id_attendee_app_user_id_event (event_id, attendee_app_user_id) WHERE event_session_id IS NULL,
  UNIQUE INDEX uq_event_attendance_event_session_id_attendee_app_user_id_session (event_session_id, attendee_app_user_id) WHERE event_session_id IS NOT NULL,
  INDEX idx_event_attendance_attendee_app_user_id_checked_in_at (attendee_app_user_id, checked_in_at DESC),
  INDEX idx_event_attendance_checked_in_at (checked_in_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_event_attendance_event_ticket_id (event_ticket_id),
  INDEX idx_event_attendance_event_attendance_source_id (event_attendance_source_id)
);
-- @@
CREATE TABLE IF NOT EXISTS network_invitation (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  inviter_app_user_id UUID NOT NULL,
  network_invitation_channel_id UUID NOT NULL,
  network_invitation_status_id UUID NOT NULL,
  invitee_email STRING(254),
  invitee_phone STRING(16),
  invitee_phone_country_id UUID,
  invite_link_id UUID,
  referral_id UUID,
  joined_app_user_id UUID,
  is_open BOOL NOT NULL DEFAULT false,
  reminder_count INT2 NOT NULL DEFAULT 0,
  sent_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  accepted_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  CONSTRAINT pk_network_invitation PRIMARY KEY (id),
  CONSTRAINT ck_network_invitation_email_lower CHECK (invitee_email IS NULL OR invitee_email = lower(invitee_email)),
  CONSTRAINT ck_network_invitation_phone_e164 CHECK (invitee_phone IS NULL OR invitee_phone ~ '^\+[1-9][0-9]{6,14}$'),
  CONSTRAINT ck_network_invitation_phone_country CHECK (invitee_phone IS NULL OR invitee_phone_country_id IS NOT NULL),
  CONSTRAINT ck_network_invitation_has_contact CHECK (num_nonnulls(invitee_email, invitee_phone) >= 1),
  CONSTRAINT fk_network_invitation_inviter_app_user_id FOREIGN KEY (inviter_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_network_invitation_network_invitation_channel_id FOREIGN KEY (network_invitation_channel_id) REFERENCES network_invitation_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_network_invitation_network_invitation_status_id FOREIGN KEY (network_invitation_status_id) REFERENCES network_invitation_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_network_invitation_invitee_phone_country_id FOREIGN KEY (invitee_phone_country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_network_invitation_invite_link_id FOREIGN KEY (invite_link_id) REFERENCES invite_link (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_network_invitation_referral_id FOREIGN KEY (referral_id) REFERENCES referral (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_network_invitation_joined_app_user_id FOREIGN KEY (joined_app_user_id) REFERENCES app_user (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_network_invitation_inviter_app_user_id_invitee_email_open (inviter_app_user_id, invitee_email) WHERE is_open AND invitee_email IS NOT NULL,
  INDEX idx_network_invitation_invitee_email_match (invitee_email) WHERE invitee_email IS NOT NULL,
  INDEX idx_network_invitation_joined_app_user_id (joined_app_user_id) WHERE joined_app_user_id IS NOT NULL,
  INDEX idx_network_invitation_sent_at (sent_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_network_invitation_network_invitation_channel_id (network_invitation_channel_id),
  INDEX idx_network_invitation_network_invitation_status_id (network_invitation_status_id),
  INDEX idx_network_invitation_invitee_phone_country_id (invitee_phone_country_id),
  INDEX idx_network_invitation_invite_link_id (invite_link_id),
  INDEX idx_network_invitation_referral_id (referral_id)
);
